    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"spacing\",\"type\":\"number\",\"label\":\"Ring spacing (vmin)\",\"default\":1.6},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Highlight\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Ink\",\"default\":\"#ec8b49\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #ec8b49;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"moire-field\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></canvas>\n    </div>\n    <script>\n      (function () {\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + Math.round(rgb[0]) + \", \" + Math.round(rgb[1]) + \", \" + Math.round(rgb[2]) + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mixRgb(from, to, amount) {\n          return [from[0] + (to[0] - from[0]) * amount, from[1] + (to[1] - from[1]) * amount, from[2] + (to[2] - from[2]) * amount];\n        }\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const duration = 10;\n        const back = channels(vars.background);\n        const fore = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const spacing = view.vmin * Math.max(0.6, Number(vars.spacing) || 1.6);\n        const reach = Math.hypot(view.width, view.height) * 1.1;\n        let mask = null;\n        let maskContext = null;\n        function rings(target, centerX, centerY) {\n          target.beginPath();\n          for (let radius = spacing; radius < reach; radius += spacing * 2) {\n            target.moveTo(centerX + radius + spacing, centerY);\n            target.arc(centerX, centerY, radius + spacing, 0, Math.PI * 2);\n            target.moveTo(centerX + radius, centerY);\n            target.arc(centerX, centerY, radius, 0, Math.PI * 2, true);\n          }\n          target.fill();\n        }\n        function draw(time) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          if (!mask) {\n            mask = document.createElement(\"canvas\");\n            mask.width = view.width;\n            mask.height = view.height;\n            maskContext = mask.getContext(\"2d\");\n          }\n          const turn = Math.PI * 2;\n          const apart = 0.5 + 0.5 * Math.sin((time / duration) * turn - Math.PI / 2);\n          const offset = view.vmin * (2 + 22 * apart);\n          const angle = time * 0.35;\n          const firstX = view.width / 2 + Math.cos(angle) * offset;\n          const firstY = view.height / 2 + Math.sin(angle) * offset * 0.7;\n          const secondX = view.width / 2 - Math.cos(angle) * offset;\n          const secondY = view.height / 2 - Math.sin(angle) * offset * 0.7;\n          maskContext.globalCompositeOperation = \"source-over\";\n          maskContext.clearRect(0, 0, view.width, view.height);\n          maskContext.fillStyle = \"#000000\";\n          rings(maskContext, firstX, firstY);\n          maskContext.globalCompositeOperation = \"xor\";\n          rings(maskContext, secondX, secondY);\n          maskContext.globalCompositeOperation = \"source-in\";\n          const paint = maskContext.createRadialGradient(view.width / 2, view.height / 2, 0, view.width / 2, view.height / 2, view.width * 0.6);\n          paint.addColorStop(0, rgba(mixRgb(accent, fore, 0.55), 1));\n          paint.addColorStop(0.45, rgba(accent, 1));\n          paint.addColorStop(1, rgba(mixRgb(accent, back, 0.75), 1));\n          maskContext.fillStyle = paint;\n          maskContext.fillRect(0, 0, view.width, view.height);\n          context.clearRect(0, 0, view.width, view.height);\n          const fade = Math.min(1, time / 0.8);\n          context.globalAlpha = fade;\n          context.drawImage(mask, 0, 0);\n          context.globalAlpha = 1;\n          const vignette = context.createRadialGradient(view.width / 2, view.height / 2, view.height * 0.3, view.width / 2, view.height / 2, view.width * 0.65);\n          vignette.addColorStop(0, rgba(back, 0));\n          vignette.addColorStop(1, rgba(back, 0.85));\n          context.fillStyle = vignette;\n          context.fillRect(0, 0, view.width, view.height);\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: duration, duration: duration, ease: \"none\", onUpdate: () => draw(proxy.time) }, 0);\n        draw(0);\n        registerTimeline(\"moire-field\", timeline);\n      })();\n    </script>\n  </body>\n</html>\n",
