    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color1Start\",\"type\":\"color\",\"label\":\"Gradient 1 Start\",\"default\":\"#FDB813\"},{\"id\":\"color1End\",\"type\":\"color\",\"label\":\"Gradient 1 End\",\"default\":\"#78C0E0\"},{\"id\":\"color2Start\",\"type\":\"color\",\"label\":\"Gradient 2 Start\",\"default\":\"#F5576C\"},{\"id\":\"color2End\",\"type\":\"color\",\"label\":\"Gradient 2 End\",\"default\":\"#2F2044\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #FDB813;\n        --fg: #f8fafc;\n        --muted: #94a3b8;\n        --accent: #38bdf8;\n        --accent-2: #f59e0b;\n        --danger: #f43f5e;\n        --ok: #34d399;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #FDB813;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"radial-gradient\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#FDB813\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const bg = document.getElementById(\"bg\");\n        const from = \"radial-gradient(circle at 20% 20%, \" + vars.color1Start + \" 0%, \" + vars.color1End + \" 60%)\";\n        const to = \"radial-gradient(circle at 80% 80%, \" + vars.color2Start + \" 0%, \" + vars.color2End + \" 100%)\";\n        const proxy = hyperbits.gradientProxy(bg, [from, to]);\n        const apply = function () {\n          proxy.apply();\n          bg.style.backgroundColor = vars.color1Start;\n          bg.style.setProperty(\"--knob-color\", vars.color1Start);\n        };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(proxy.proxy, { progress: 0 }, { progress: 1, duration: 3, ease: \"none\", onUpdate: apply }, 0);\n        timeline.fromTo(bg, { x: 0 }, { x: 0.5, duration: 3, ease: \"none\" }, 0);\n        registerTimeline(\"radial-gradient\", timeline);\n        apply();\n\n      })();\n    </script>\n  </body>\n</html>\n",
