    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#4fb6ec\"},{\"id\":\"frames\",\"type\":\"number\",\"label\":\"Tubes\",\"default\":5},{\"id\":\"dots\",\"type\":\"number\",\"label\":\"Dots per ring\",\"default\":12}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #4fb6ec;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"dot-tunnel\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const tubes = Math.max(1, Math.round(Number(vars.frames) || 5));\n        const dots = Math.max(6, Math.round(Number(vars.dots) || 12));\n        const lane = view.height / tubes;\n        const radius = lane * 0.36;\n        const gap = view.vmin * 3;\n        const rings = Math.ceil((view.width + gap * 4) / gap);\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          for (let tube = 0; tube < tubes; tube += 1) {\n            const direction = tube % 2 === 0 ? 1 : -1;\n            const centerY = lane * (tube + 0.5);\n            const points = [];\n            for (let ring = 0; ring < rings; ring += 1) {\n              const along = (((ring + direction * phase * 3) % rings) + rings) % rings;\n              const pointX = along * gap - gap * 2;\n              const share = pointX / view.width;\n              for (let dot = 0; dot < dots; dot += 1) {\n                const theta = (turn * dot) / dots + share * 4 * direction + (turn / dots) * phase * 2 + tube;\n                points.push({ pointX, pointY: centerY + Math.cos(theta) * radius, depth: Math.sin(theta), stripe: Math.sin(theta * 2 - share * 3) });\n              }\n            }\n            points.sort((left, right) => left.depth - right.depth);\n            for (const point of points) {\n              const front = (point.depth + 1) / 2;\n              const lit = point.stripe > 0.8;\n              context.fillStyle = rgba(lit ? accent : foreground, (lit ? 0.55 : 0.32) * (0.25 + 0.75 * front));\n              context.beginPath();\n              context.arc(point.pointX, point.pointY, view.vmin * (0.16 + 0.24 * front), 0, turn);\n              context.fill();\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"dot-tunnel\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
