    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#f2f0e5\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#100f0f\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#9d8af0\"},{\"id\":\"sway\",\"type\":\"number\",\"label\":\"Sway (degrees)\",\"default\":4}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #f2f0e5;\n        --fg: #100f0f;\n        --accent: #9d8af0;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #f2f0e5;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"floating-shapes\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#f2f0e5\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const tones = [mix(accent, background, 0.4), mix(accent, background, 0.65), mix(foreground, background, 0.75)];\n        const sway = ((Number(vars.sway) || 4) * Math.PI) / 180;\n        const unit = view.vmin;\n        const kinds = [\"circle\", \"triangle\", \"square\", \"ring\", \"diamond\", \"half\"];\n        const strands = [...Array(11).keys()].map((index) => {\n          const key = \"garland-\" + index;\n          const pieces = hyperbits.randomInt(key + \"-n\", 3, 6);\n          return {\n            anchorX: view.width * ((index + 0.5) / 11 + hyperbits.randomFloat(key + \"-x\", -0.015, 0.015)),\n            rate: hyperbits.pick(key + \"-r\", [1, 1, 2]),\n            shift: hyperbits.random(key + \"-s\"),\n            pieces: [...Array(pieces).keys()].map((piece) => ({\n              gap: unit * hyperbits.randomFloat(key + \"-g\" + piece, 10, 17),\n              kind: hyperbits.pick(key + \"-k\" + piece, kinds),\n              size: unit * hyperbits.randomFloat(key + \"-z\" + piece, 2.4, 4.4),\n              tone: tones[(index + piece) % tones.length],\n              spin: hyperbits.pick(key + \"-t\" + piece, [-1, 1]),\n            })),\n          };\n        });\n        function shape(kind, size) {\n          context.beginPath();\n          if (kind === \"circle\") context.arc(0, size, size, 0, turn);\n          else if (kind === \"ring\") {\n            context.arc(0, size, size, 0, turn);\n            context.arc(0, size, size * 0.55, 0, turn, true);\n          } else if (kind === \"triangle\") {\n            context.moveTo(0, 0);\n            context.lineTo(size, size * 1.7);\n            context.lineTo(-size, size * 1.7);\n          } else if (kind === \"square\") context.rect(-size * 0.85, 0, size * 1.7, size * 1.7);\n          else if (kind === \"half\") context.arc(0, 0, size * 1.1, 0, Math.PI);\n          else {\n            context.moveTo(0, 0);\n            context.lineTo(size * 0.8, size);\n            context.lineTo(0, size * 2);\n            context.lineTo(-size * 0.8, size);\n          }\n          context.closePath();\n          context.fill(\"evenodd\");\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          for (const strand of strands) {\n            const angle = sway * Math.sin(turn * (phase * strand.rate + strand.shift));\n            context.save();\n            context.translate(strand.anchorX, -unit);\n            context.rotate(angle);\n            let depth = 0;\n            for (const piece of strand.pieces) {\n              depth += piece.gap;\n              context.strokeStyle = rgba(foreground, 0.18);\n              context.lineWidth = unit * 0.12;\n              context.beginPath();\n              context.moveTo(0, depth - piece.gap);\n              context.lineTo(0, depth);\n              context.stroke();\n              context.save();\n              context.translate(0, depth);\n              context.rotate(0.25 * Math.sin(turn * (phase * 2 * piece.spin + strand.shift + depth / view.height)));\n              context.fillStyle = rgba(piece.tone, 1);\n              shape(piece.kind, piece.size);\n              context.restore();\n              depth += piece.size * 2;\n            }\n            context.restore();\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"floating-shapes\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
