    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#4fb6ec\"},{\"id\":\"rings\",\"type\":\"number\",\"label\":\"Orbits\",\"default\":16},{\"id\":\"seed\",\"type\":\"number\",\"label\":\"Seed\",\"default\":3}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #4fb6ec;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"gyro-rings\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const count = Math.max(1, Math.round(Number(vars.rings) || 16));\n        const seed = Number(vars.seed) || 0;\n        const centerX = -view.width * 0.25;\n        const centerY = view.height * 1.35;\n        const squash = 0.62;\n        const tilt = -0.18;\n        const innerRadius = Math.hypot(centerX, centerY - view.height) * 0.9;\n        const outerRadius = Math.hypot(view.width - centerX, centerY) * 1.02;\n        const orbits = [...Array(count).keys()].map((index) => {\n          const key = \"arc-\" + seed + \"-\" + index;\n          return {\n            radius: innerRadius + ((outerRadius - innerRadius) * (index + 0.5)) / count,\n            planets: [0, 1, 2, 3, 4, 5].map((planet) => hyperbits.randomFloat(key + \"-p\", 0, turn) + (turn * planet) / 6),\n            laps: hyperbits.pick(key + \"-l\", [1, 1, -1]),\n            size: view.vmin * hyperbits.randomFloat(key + \"-s\", 0.35, 0.8),\n            lit: hyperbits.random(key + \"-lit\") > 0.8,\n          };\n        });\n        function place(orbit, angle) {\n          const flatX = Math.cos(angle) * orbit.radius;\n          const flatY = Math.sin(angle) * orbit.radius * squash;\n          return [centerX + flatX * Math.cos(tilt) - flatY * Math.sin(tilt), centerY + flatX * Math.sin(tilt) + flatY * Math.cos(tilt)];\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          context.lineCap = \"round\";\n          for (const orbit of orbits) {\n            context.strokeStyle = rgba(foreground, 0.14);\n            context.lineWidth = view.vmin * 0.12;\n            context.beginPath();\n            context.ellipse(centerX, centerY, orbit.radius, orbit.radius * squash, tilt, 0, turn);\n            context.stroke();\n            const color = orbit.lit ? accent : foreground;\n            for (const start of orbit.planets) {\n              const angle = start + (turn / 6) * phase * orbit.laps;\n              for (let step = 1; step <= 18; step += 1) {\n                const [fromX, fromY] = place(orbit, angle - orbit.laps * step * 0.004);\n                const [toX, toY] = place(orbit, angle - orbit.laps * (step - 1) * 0.004);\n                context.strokeStyle = rgba(color, 0.3 * (1 - step / 18));\n                context.lineWidth = orbit.size;\n                context.beginPath();\n                context.moveTo(fromX, fromY);\n                context.lineTo(toX, toY);\n                context.stroke();\n              }\n              const [planetX, planetY] = place(orbit, angle);\n              context.fillStyle = rgba(color, 0.6);\n              context.beginPath();\n              context.arc(planetX, planetY, orbit.size, 0, turn);\n              context.fill();\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"gyro-rings\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
