    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#ef5da8\"},{\"id\":\"pitch\",\"type\":\"number\",\"label\":\"Dot pitch (vmin)\",\"default\":2.2}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #ef5da8;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"halftone-sweep\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const pitch = view.vmin * Math.max(1, Number(vars.pitch) || 2.2);\n        const columns = Math.ceil(view.width / pitch) + 1;\n        const rows = Math.ceil(view.height / pitch) + 1;\n        const clouds = [];\n        for (let row = 0; row < 3; row += 1) {\n          for (let column = 0; column < 4; column += 1) {\n            const key = \"cloud-\" + row + \"-\" + column;\n            clouds.push({\n              homeX: view.width * ((column + 0.5 + hyperbits.randomFloat(key + \"-x\", -0.2, 0.2)) / 4),\n              homeY: view.height * ((row + 0.5 + hyperbits.randomFloat(key + \"-y\", -0.2, 0.2)) / 3),\n              radius: view.vmin * hyperbits.randomFloat(key + \"-r\", 14, 22),\n              orbit: view.vmin * hyperbits.randomFloat(key + \"-o\", 4, 8),\n              shift: hyperbits.random(key + \"-s\"),\n              direction: hyperbits.pick(key + \"-d\", [-1, 1]),\n            });\n          }\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          const centers = clouds.map((cloud) => {\n            const angle = turn * (cloud.direction * phase + cloud.shift);\n            return { cloud, cloudX: cloud.homeX + Math.cos(angle) * cloud.orbit, cloudY: cloud.homeY + Math.sin(angle) * cloud.orbit };\n          });\n          const dotFill = rgba(accent, 0.55);\n          const dustFill = rgba(foreground, 0.12);\n          for (let row = 0; row < rows; row += 1) {\n            for (let column = 0; column < columns; column += 1) {\n              const dotX = column * pitch;\n              const dotY = row * pitch;\n              let amount = 0;\n              for (const { cloud, cloudX, cloudY } of centers) {\n                const distance = Math.hypot(dotX - cloudX, dotY - cloudY) / cloud.radius;\n                amount = Math.max(amount, Math.exp(-distance * distance * 1.8));\n              }\n              const radius = pitch * 0.42 * amount;\n              if (radius < view.vmin * 0.12) {\n                context.fillStyle = dustFill;\n                context.fillRect(dotX - view.vmin * 0.08, dotY - view.vmin * 0.08, view.vmin * 0.16, view.vmin * 0.16);\n                continue;\n              }\n              context.fillStyle = dotFill;\n              context.beginPath();\n              context.arc(dotX, dotY, radius, 0, turn);\n              context.fill();\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"halftone-sweep\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
