    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#4fb6ec\"},{\"id\":\"ridges\",\"type\":\"number\",\"label\":\"Ridge rows\",\"default\":80}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #4fb6ec;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"horizon-grid\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const ridges = Math.max(8, Math.round(Number(vars.ridges) || 80));\n        const horizon = view.height * 0.06;\n        const centerX = view.width * 0.5;\n        const focal = view.height * 0.3;\n        const spacing = 0.22;\n        const near = 0.25;\n        const far = ridges * spacing;\n        const rowsPerLoop = 8;\n        const period = rowsPerLoop * spacing;\n        const samples = 80;\n        function height(worldX, worldZ) {\n          const along = (turn * worldZ) / period;\n          return 0.5 * Math.sin(along + worldX * 0.4) + 0.3 * Math.sin(along * 2 - worldX * 0.8 + 1.3) + 0.15 * Math.sin(along * 3 + worldX * 1.6 + 2.1);\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          const travel = phase * period;\n          const sway = Math.sin(turn * phase) * 0.4;\n          const first = Math.ceil((travel + near) / spacing);\n          const last = Math.floor((travel + far) / spacing);\n          context.lineJoin = \"round\";\n          for (let row = last; row >= first; row -= 1) {\n            const worldZ = row * spacing;\n            const depth = worldZ - travel;\n            const fog = Math.pow(1 - (depth - near) / (far - near), 0.9);\n            context.beginPath();\n            for (let sample = 0; sample <= samples; sample += 1) {\n              const worldX = (sample / samples - 0.5) * (depth * 7 + 3) + sway;\n              const pointX = centerX + ((worldX - sway) * focal) / depth;\n              const pointY = horizon + ((2.2 - height(worldX, worldZ)) * focal) / depth;\n              if (sample === 0) context.moveTo(pointX, pointY);\n              else context.lineTo(pointX, pointY);\n            }\n            context.lineTo(view.width * 2, view.height * 2);\n            context.lineTo(-view.width, view.height * 2);\n            context.closePath();\n            context.fillStyle = rgba(background, 1);\n            context.fill();\n            const marked = row % 4 === 0;\n            context.strokeStyle = rgba(marked ? accent : foreground, fog * (marked ? 0.55 : 0.32));\n            context.lineWidth = Math.max(view.vmin * 0.1, (view.vmin * 0.28) / depth);\n            context.stroke();\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"horizon-grid\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
