    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#f2f0e5\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#100f0f\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#ef5da8\"},{\"id\":\"dots\",\"type\":\"number\",\"label\":\"Florets per flower\",\"default\":90}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #f2f0e5;\n        --fg: #100f0f;\n        --accent: #ef5da8;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #f2f0e5;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"phyllotaxis-bloom\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#f2f0e5\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const petal = mix(accent, background, 0.45);\n        const petalLight = mix(accent, background, 0.65);\n        const seedTone = mix(foreground, background, 0.55);\n        const florets = Math.max(20, Math.round(Number(vars.dots) || 90));\n        const golden = Math.PI * (3 - Math.sqrt(5));\n        const ease = hyperbits.Easing.easeInOutSine;\n        const cellX = view.vmin * 20;\n        const cellY = view.vmin * 17;\n        const radius = view.vmin * 7.2;\n        const flowers = [];\n        for (let row = -1; row * cellY < view.height + cellY; row += 1) {\n          for (let column = -1; column * cellX < view.width + cellX; column += 1) {\n            flowers.push({ centerX: column * cellX + (row % 2 === 0 ? 0 : cellX / 2), centerY: row * cellY });\n          }\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          const spread = radius / Math.sqrt(florets);\n          const seeds = Math.round(florets * 0.3);\n          for (const flower of flowers) {\n            const lag = flower.centerX / view.width + flower.centerY / view.height * 0.5;\n            const open = ease(0.5 + 0.5 * Math.sin(turn * (phase - lag)));\n            for (let index = florets - 1; index >= 0; index -= 1) {\n              const distance = spread * Math.sqrt(index + 0.5);\n              const angle = index * golden;\n              const floretX = flower.centerX + Math.cos(angle) * distance;\n              const floretY = flower.centerY + Math.sin(angle) * distance;\n              if (index < seeds) {\n                context.fillStyle = rgba(seedTone, 0.7);\n                context.beginPath();\n                context.arc(floretX, floretY, spread * 0.38, 0, turn);\n                context.fill();\n                continue;\n              }\n              const length = spread * (1 + 1.6 * open);\n              context.save();\n              context.translate(floretX, floretY);\n              context.rotate(angle);\n              context.fillStyle = rgba(index % 3 === 0 ? petalLight : petal, 1);\n              context.beginPath();\n              context.ellipse(length * 0.5, 0, length * 0.5, spread * 0.55, 0, 0, turn);\n              context.fill();\n              context.restore();\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"phyllotaxis-bloom\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
