    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#9d8af0\"},{\"id\":\"pinwheels\",\"type\":\"number\",\"label\":\"Pinwheels per row\",\"default\":14},{\"id\":\"seed\",\"type\":\"number\",\"label\":\"Seed\",\"default\":5}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #9d8af0;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"pinwheel-grid\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const perRow = Math.max(2, Math.round(Number(vars.pinwheels) || 14));\n        const seed = Number(vars.seed) || 0;\n        const plants = [];\n        for (let row = 0; row < 6; row += 1) {\n          const depth = 1 - row / 6;\n          const count = Math.round(perRow * (0.85 + row * 0.06));\n          for (let index = 0; index < count; index += 1) {\n            const key = \"meadow-\" + seed + \"-\" + row + \"-\" + index;\n            plants.push({\n              depth,\n              baseX: view.width * ((index + hyperbits.randomFloat(key + \"-x\", 0.2, 0.8)) / count),\n              baseY: view.height * (1.04 - 0.165 * row),\n              height: view.vmin * (7 + 6 * depth) * hyperbits.randomFloat(key + \"-h\", 0.8, 1.2),\n              radius: view.vmin * (2.4 + 1.6 * depth),\n              tone: mix(hyperbits.random(key + \"-t\") > 0.75 ? foreground : accent, background, 0.4 + 0.15 * (1 - depth)),\n              fold: mix(accent, background, 0.7 + 0.1 * (1 - depth)),\n              spin: hyperbits.pick(key + \"-s\", [1, 1, -1]),\n            });\n          }\n        }\n        plants.sort((left, right) => left.depth - right.depth);\n        function wheel(radius, tone, fold) {\n          for (let blade = 0; blade < 4; blade += 1) {\n            context.fillStyle = rgba(tone, 1);\n            context.beginPath();\n            context.moveTo(0, 0);\n            context.lineTo(radius, 0);\n            context.lineTo(radius, -radius);\n            context.closePath();\n            context.fill();\n            context.fillStyle = rgba(fold, 1);\n            context.beginPath();\n            context.moveTo(0, 0);\n            context.lineTo(radius, -radius);\n            context.lineTo(radius * 0.25, -radius * 0.55);\n            context.closePath();\n            context.fill();\n            context.rotate(Math.PI / 2);\n          }\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          for (const plant of plants) {\n            const gust = Math.pow(0.5 + 0.5 * Math.cos(turn * (phase - plant.baseX / view.width)), 3);\n            const tipX = plant.baseX + view.vmin * (0.6 + 2.4 * gust) * plant.depth;\n            const tipY = plant.baseY - plant.height;\n            context.strokeStyle = rgba(foreground, 0.12 + 0.18 * plant.depth);\n            context.lineWidth = view.vmin * (0.1 + 0.18 * plant.depth);\n            context.beginPath();\n            context.moveTo(plant.baseX, plant.baseY);\n            context.quadraticCurveTo(plant.baseX, plant.baseY - plant.height * 0.55, tipX, tipY);\n            context.stroke();\n            context.save();\n            context.translate(tipX, tipY);\n            context.rotate(plant.spin * (turn * phase + 0.8 * Math.sin(turn * (phase - plant.baseX / view.width))));\n            wheel(plant.radius, plant.tone, plant.fold);\n            context.restore();\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"pinwheel-grid\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
