    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#ef5da8\"},{\"id\":\"columns\",\"type\":\"number\",\"label\":\"Columns\",\"default\":96},{\"id\":\"seed\",\"type\":\"number\",\"label\":\"Seed\",\"default\":2}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #ef5da8;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"pixel-rain\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const muted = mix(foreground, background, 0.45);\n        const columns = Math.max(16, Math.round(Number(vars.columns) || 96));\n        const seed = Number(vars.seed) || 0;\n        const cell = view.width / columns;\n        const rows = Math.ceil(view.height / cell);\n        const block = cell * 0.82;\n        const drops = [...Array(Math.round(columns * 1.3)).keys()].map((index) => {\n          const key = \"drop-\" + seed + \"-\" + index;\n          return {\n            column: hyperbits.randomInt(key + \"-c\", 0, columns - 1),\n            start: hyperbits.randomInt(key + \"-s\", -14, -2),\n            land: Math.round(rows * hyperbits.randomFloat(key + \"-g\", 0.2, 0.98)),\n            offset: hyperbits.random(key + \"-o\"),\n            laps: hyperbits.pick(key + \"-l\", [1, 1, 2]),\n            bright: hyperbits.random(key + \"-b\") > 0.75,\n          };\n        });\n        function pixel(column, row, color, alpha) {\n          if (row < 0 || row >= rows || alpha <= 0.01) return;\n          const wrapped = ((column % columns) + columns) % columns;\n          context.fillStyle = rgba(color, alpha);\n          context.fillRect(wrapped * cell + (cell - block) / 2, row * cell + (cell - block) / 2, block, block);\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          for (const drop of drops) {\n            const progress = (((drop.offset + phase * drop.laps) % 1) + 1) % 1;\n            const color = drop.bright ? accent : muted;\n            const fallShare = 0.7;\n            if (progress < fallShare) {\n              const fall = Math.pow(progress / fallShare, 1.6);\n              const row = Math.floor(drop.start + (drop.land - drop.start) * fall);\n              const drift = Math.floor((row - drop.start) * 0.3);\n              pixel(drop.column + drift, row, color, 0.85);\n              pixel(drop.column + drift, row - 1, color, 0.45);\n              pixel(drop.column + drift - 1, row - 2, color, 0.2);\n            } else {\n              const splash = (progress - fallShare) / (1 - fallShare);\n              const drift = Math.floor((drop.land - drop.start) * 0.3);\n              const reach = 1 + Math.floor(splash * 4);\n              const alpha = 0.7 * Math.pow(1 - splash, 1.5);\n              pixel(drop.column + drift - reach, drop.land, color, alpha);\n              pixel(drop.column + drift + reach, drop.land, color, alpha);\n              pixel(drop.column + drift, drop.land - Math.floor(reach / 2) - 1, color, alpha * 0.6);\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"pixel-rain\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
