    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#f2652a\"},{\"id\":\"streaks\",\"type\":\"number\",\"label\":\"Trails\",\"default\":20},{\"id\":\"seed\",\"type\":\"number\",\"label\":\"Seed\",\"default\":9}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #f2652a;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"speed-streaks\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const warm = mix(accent, foreground, 0.4);\n        const count = Math.max(1, Math.round(Number(vars.streaks) || 20));\n        const seed = Number(vars.seed) || 0;\n        const columns = Math.ceil(Math.sqrt(count * (view.width / view.height)));\n        const rows = Math.ceil(count / columns);\n        const tones = [accent, warm, accent, foreground];\n        const trails = [...Array(count).keys()].map((index) => {\n          const key = \"trail-\" + seed + \"-\" + index;\n          return {\n            homeX: ((index % columns) + 0.5) / columns,\n            homeY: (Math.floor(index / columns) + 0.5) / rows,\n            rateY: hyperbits.pick(key + \"-fy\", [1, 2]),\n            shiftX: hyperbits.random(key + \"-sx\"),\n            shiftY: hyperbits.random(key + \"-sy\"),\n            reachX: hyperbits.randomFloat(key + \"-ax\", 0.6, 0.9) / columns,\n            reachY: hyperbits.randomFloat(key + \"-ay\", 0.5, 0.8) / rows,\n            width: view.vmin * hyperbits.randomFloat(key + \"-w\", 0.18, 0.4),\n            length: hyperbits.randomFloat(key + \"-l\", 0.3, 0.5),\n            color: tones[index % tones.length],\n          };\n        });\n        function position(trail, time) {\n          return [\n            view.width * (trail.homeX + trail.reachX * Math.sin(turn * (time + trail.shiftX))),\n            view.height * (trail.homeY + trail.reachY * Math.sin(turn * (time * trail.rateY + trail.shiftY))),\n          ];\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          context.lineCap = \"round\";\n          const pieces = 60;\n          for (const trail of trails) {\n            let previous = position(trail, phase - trail.length);\n            for (let piece = 1; piece <= pieces; piece += 1) {\n              const share = piece / pieces;\n              const current = position(trail, phase - trail.length * (1 - share));\n              context.strokeStyle = rgba(trail.color, 0.45 * Math.pow(share, 1.6));\n              context.lineWidth = trail.width;\n              context.beginPath();\n              context.moveTo(previous[0], previous[1]);\n              context.lineTo(current[0], current[1]);\n              context.stroke();\n              previous = current;\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"speed-streaks\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
