    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#9d8af0\"},{\"id\":\"rings\",\"type\":\"number\",\"label\":\"Bands\",\"default\":11},{\"id\":\"seed\",\"type\":\"number\",\"label\":\"Seed\",\"default\":6}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #9d8af0;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"truchet-weave\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const rings = Math.max(2, Math.round(Number(vars.rings) || 11));\n        const seed = Number(vars.seed) || 0;\n        const sectors = 120;\n        const centerX = view.width * 1.9;\n        const centerY = view.height * 3.2;\n        const corners = [[0, 0], [view.width, 0], [0, view.height], [view.width, view.height]];\n        const distances = corners.map(([cornerX, cornerY]) => Math.hypot(cornerX - centerX, cornerY - centerY));\n        const angles = corners.map(([cornerX, cornerY]) => Math.atan2(cornerY - centerY, cornerX - centerX));\n        const inner = Math.min(...distances) - view.vmin * 4;\n        const outer = Math.max(...distances) + view.vmin * 4;\n        const band = (outer - inner) / rings;\n        const width = turn / sectors;\n        const fromAngle = Math.min(...angles) - width * 4;\n        const toAngle = Math.max(...angles) + width * 4;\n        const slots = 6;\n        const flips = [];\n        for (let ring = 0; ring < rings; ring += 1) {\n          for (let slot = 0; slot < slots; slot += 1) {\n            flips.push(hyperbits.random(\"arcs-\" + seed + \"-\" + ring + \"-\" + slot) > 0.5);\n          }\n        }\n        function polar(distance, angle) {\n          return [centerX + Math.cos(angle) * distance, centerY + Math.sin(angle) * distance];\n        }\n        function curve(fromDistance, startAngle, cornerDistance, cornerAngle, toDistance, endAngle) {\n          const [startX, startY] = polar(fromDistance, startAngle);\n          const [controlX, controlY] = polar(cornerDistance, cornerAngle);\n          const [endX, endY] = polar(toDistance, endAngle);\n          context.moveTo(startX, startY);\n          context.quadraticCurveTo(controlX, controlY, endX, endY);\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          context.lineCap = \"round\";\n          for (let ring = 0; ring < rings; ring += 1) {\n            const direction = ring % 2 === 0 ? 1 : -1;\n            const offset = direction * width * slots * phase;\n            const low = inner + ring * band;\n            const high = low + band;\n            const middle = (low + high) / 2;\n            context.strokeStyle = rgba(ring % 4 === 1 ? accent : foreground, ring % 4 === 1 ? 0.4 : 0.2);\n            context.lineWidth = Math.min(band * 0.05, view.vmin * 0.6);\n            context.beginPath();\n            const firstSector = Math.floor((fromAngle - offset) / width);\n            const lastSector = Math.ceil((toAngle - offset) / width);\n            for (let sector = firstSector; sector <= lastSector; sector += 1) {\n              const start = sector * width + offset;\n              const end = start + width;\n              const center = start + width / 2;\n              const slot = ((sector % slots) + slots) % slots;\n              if (flips[ring * slots + slot]) {\n                curve(low, center, low, start, middle, start);\n                curve(high, center, high, end, middle, end);\n              } else {\n                curve(low, center, low, end, middle, end);\n                curve(high, center, high, start, middle, start);\n              }\n            }\n            context.stroke();\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"truchet-weave\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
