    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#f2652a\"},{\"id\":\"lines\",\"type\":\"number\",\"label\":\"Ribbons\",\"default\":6}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #f2652a;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"wave-stack\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mix(from, to, amount) {\n          return from.map((value, index) => Math.round(value + (to[index] - value) * amount));\n        }\n        const background = channels(vars.background);\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const front = mix(accent, background, 0.66);\n        const frontShade = mix(accent, background, 0.78);\n        const back = mix(foreground, background, 0.85);\n        const ribbons = Math.max(1, Math.round(Number(vars.lines) || 6));\n        const stripes = 8;\n        const slices = 90;\n        const spacing = (view.height * 1.6) / ribbons;\n        const width = spacing * 0.62;\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          for (let ribbon = 0; ribbon < ribbons; ribbon += 1) {\n            const offset = ribbon / ribbons;\n            const columns = [];\n            for (let slice = 0; slice <= slices; slice += 1) {\n              const progress = slice / slices;\n              columns.push({\n                sliceX: -view.vw * 5 + progress * view.vw * 110,\n                centerY: -view.height * 0.3 + spacing * (ribbon + 0.5) + view.height * 0.35 * (progress - 0.5) * -1 + view.vh * 4 * Math.sin(turn * (progress * 0.8 + offset - phase)),\n                twist: turn * (progress * 0.5 + offset * 1.7 - phase),\n              });\n            }\n            for (let slice = 0; slice < slices; slice += 1) {\n              const left = columns[slice];\n              const right = columns[slice + 1];\n              const facing = Math.cos(left.twist) >= 0;\n              for (let stripe = 0; stripe < stripes; stripe += 1) {\n                const top = -0.5 + stripe / stripes;\n                const bottom = top + 1 / stripes;\n                context.fillStyle = rgba(facing ? (stripe % 2 === 0 ? front : frontShade) : back, 1);\n                context.beginPath();\n                context.moveTo(left.sliceX, left.centerY + top * width * Math.cos(left.twist));\n                context.lineTo(right.sliceX + 0.6, right.centerY + top * width * Math.cos(right.twist));\n                context.lineTo(right.sliceX + 0.6, right.centerY + bottom * width * Math.cos(right.twist));\n                context.lineTo(left.sliceX, left.centerY + bottom * width * Math.cos(left.twist));\n                context.closePath();\n                context.fill();\n              }\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"wave-stack\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
