    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Foreground\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#4fb6ec\"},{\"id\":\"sides\",\"type\":\"number\",\"label\":\"Polygon sides\",\"default\":6},{\"id\":\"count\",\"type\":\"number\",\"label\":\"Polygons\",\"default\":54}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #4fb6ec;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"zoom-polygons\"\n      data-start=\"0\"\n      data-duration=\"12\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"12\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"12\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const context = canvas.getContext(\"2d\");\n        const loop = 12;\n        const turn = Math.PI * 2;\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + rgb[0] + \", \" + rgb[1] + \", \" + rgb[2] + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        const foreground = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const sides = Math.max(3, Math.round(Number(vars.sides) || 6));\n        const count = Math.max(1, Math.round(Number(vars.count) || 54));\n        const shapes = [...Array(count).keys()].map((index) => {\n          const key = \"drift-\" + index;\n          const layer = index % 3;\n          return {\n            layer,\n            homeX: hyperbits.random(key + \"-x\"),\n            homeY: (index * 0.618034 + hyperbits.randomFloat(key + \"-y\", 0, 0.05)) % 1,\n            radius: view.vmin * (2.2 + layer * 2.6) * hyperbits.randomFloat(key + \"-r\", 0.8, 1.2),\n            tilt: hyperbits.randomFloat(key + \"-t\", 0, turn),\n            spin: hyperbits.pick(key + \"-s\", [-1, 1]),\n            inner: hyperbits.random(key + \"-i\") > 0.7,\n            accent: hyperbits.random(key + \"-a\") > 0.85,\n          };\n        }).sort((left, right) => left.layer - right.layer);\n        function polygon(centerX, centerY, radius, angle) {\n          context.beginPath();\n          for (let corner = 0; corner <= sides; corner += 1) {\n            const theta = angle + (turn * corner) / sides;\n            const pointX = centerX + Math.cos(theta) * radius;\n            const pointY = centerY + Math.sin(theta) * radius;\n            if (corner === 0) context.moveTo(pointX, pointY);\n            else context.lineTo(pointX, pointY);\n          }\n          context.closePath();\n        }\n        function draw(phase) {\n          if (!context || typeof context.stroke !== \"function\") return;\n          context.clearRect(0, 0, view.width, view.height);\n          context.lineJoin = \"round\";\n          for (const shape of shapes) {\n            const orbit = view.vmin * (1.5 + 1.5 * shape.layer);\n            const centerX = shape.homeX * view.width + Math.cos(turn * (phase + shape.homeY)) * orbit;\n            const centerY = shape.homeY * view.height + Math.sin(turn * (phase + shape.homeY)) * orbit;\n            const angle = shape.tilt + shape.spin * (turn / sides) * phase;\n            const alpha = 0.16 + 0.14 * shape.layer;\n            polygon(centerX, centerY, shape.radius, angle);\n            context.strokeStyle = rgba(shape.accent ? accent : foreground, shape.accent ? alpha + 0.15 : alpha);\n            context.lineWidth = view.vmin * (0.1 + 0.06 * shape.layer);\n            context.stroke();\n            if (shape.inner) {\n              polygon(centerX, centerY, shape.radius * 0.5, -angle);\n              context.stroke();\n            }\n          }\n        }\n        const proxy = { time: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: loop, duration: loop, ease: \"none\", onUpdate: () => draw((proxy.time % loop) / loop) }, 0);\n        draw(0);\n        registerTimeline(\"zoom-polygons\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
