    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Firefly color\",\"default\":\"#ccff00\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #ccff00;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"fireflies\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const canvas = document.getElementById(\"stage\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"spawner-0\",\n            rate: 0.2,\n            max: 200,\n            position: { x: view.width / 2, y: view.height / 2 },\n            area: { width: view.width, height: view.height },\n            velocity: { x: 0.5, y: 0.5, varianceX: 1, varianceY: 1 },\n            lifespan: 100,\n          }],\n          behaviors: [\n            { id: \"wiggle\", handler: hyperbits.createWiggle(2, 0.1, 1) },\n            { id: \"fade\", handler: hyperbits.createOpacityOverLife([0, 1, 0]) },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, {\n          color: vars.color,\n          size: view.vmin,\n          glow: 5,\n          glowStops: [[0, 0.55], [0.43, 0.3], [0.71, 0.1], [1, 0]],\n          shape: \"circle\",\n        });\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"fireflies\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
