    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Spark color\",\"default\":\"#ebb03b\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"particles-fountain\"\n      data-start=\"0\"\n      data-duration=\"2\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"2\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"2\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const vmax = view.vmax;\n        bg.style.backgroundColor = vars.background;\n        const canvas = document.getElementById(\"stage\");\n        canvas.setAttribute(\"data-color\", vars.color);\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const variants = [\n          { size: vmax * 1, color: vars.color + \"99\" },\n          { size: vmax * 2, color: vars.color + \"22\" },\n          { size: vmax * 1.5, color: \"#808080\" },\n          { size: vmax * 30, color: \"rgba(176, 126, 223, 0.05)\" },\n        ];\n        const variantOf = function (particle) {\n          return variants[Math.floor(particle.seed * variants.length)];\n        };\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"spawner-0\",\n            rate: 10,\n            burst: 20,\n            startFrame: 100,\n            max: 200,\n            position: { x: view.width / 2, y: view.height * 1.1 },\n            area: { width: view.width * 0.1, height: 0 },\n            velocity: { x: 0, y: -view.height * 0.05, varianceX: view.width * 0.1, varianceY: view.height * 0.01 },\n            lifespan: 100,\n          }],\n          behaviors: [{ id: \"gravity\", handler: hyperbits.createGravity({ y: 0.2 }) }],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, {\n          shape: \"glow\",\n          size: function (particle) { return variantOf(particle).size * Math.SQRT1_2; },\n          color: function (particle) { return variantOf(particle).color; },\n          offset: function (particle) { const size = variantOf(particle).size; return { x: size / 2, y: size / 2 }; },\n        });\n        timeline.to({}, { duration: 2 }, 0);\n        registerTimeline(\"particles-fountain\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
