    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Cell color\",\"default\":\"#ffffff\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"particles-grid\"\n      data-start=\"0\"\n      data-duration=\"6.667\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6.667\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6.667\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const vmax = view.vmax;\n        bg.style.backgroundColor = vars.background;\n        const canvas = document.getElementById(\"stage\");\n        canvas.setAttribute(\"data-color\", vars.color);\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const gridSize = Math.floor(view.width * 0.05);\n        const jumpInterval = 30;\n        const snapToGrid = function (particle, age) {\n          particle.position.x = Math.floor(particle.position.x / gridSize) * gridSize;\n          particle.position.y = Math.floor(particle.position.y / gridSize) * gridSize;\n          if (age % jumpInterval === 0 && age > 0) {\n            const step = Math.floor(age / jumpInterval);\n            const dir = (particle.seed + step) % 4;\n            if (dir === 0) particle.position.x += gridSize;\n            if (dir === 1) particle.position.x -= gridSize;\n            if (dir === 2) particle.position.y += gridSize;\n            if (dir === 3) particle.position.y -= gridSize;\n          }\n        };\n        const fadeIn = function (particle, age) {\n          particle.opacity = Math.min(1, Math.max(0, age / 10));\n        };\n        const shapes = [\"square\", \"circle\", \"diamond\"];\n        const alphas = [(0x22 / 255) * 0.8, (0x5f / 255) * 0.8, (0x5f / 255) * 0.8];\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"spawner-0\",\n            rate: 1,\n            max: 50,\n            position: { x: view.width / 2, y: view.height / 2 },\n            area: { width: view.width * 0.52, height: view.height * 0.74 },\n            lifespan: 150,\n          }],\n          behaviors: [\n            { id: \"snap\", handler: snapToGrid },\n            { id: \"fade\", handler: fadeIn },\n          ],\n        });\n        const red = parseInt(vars.color.slice(1, 3), 16);\n        const green = parseInt(vars.color.slice(3, 5), 16);\n        const blue = parseInt(vars.color.slice(5, 7), 16);\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, {\n          size: gridSize,\n          shape: function (particle) { return shapes[Math.floor(particle.seed * shapes.length)]; },\n          color: function (particle) {\n            const alpha = alphas[Math.floor(particle.seed * shapes.length)];\n            return \"rgba(\" + red + \", \" + green + \", \" + blue + \", \" + alpha + \")\";\n          },\n          offset: { x: gridSize / 2, y: gridSize / 2 },\n        });\n        timeline.to({}, { duration: 6.667 }, 0);\n        registerTimeline(\"particles-grid\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
