    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Flake color\",\"default\":\"#ffffff\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#01050e\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #01050e;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #01050e;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"particles-snow\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#01050e\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const vmax = view.vmax;\n        bg.style.backgroundColor = vars.background;\n        const canvas = document.getElementById(\"stage\");\n        canvas.setAttribute(\"data-color\", vars.color);\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const variants = [\n          { size: vmin * 1, color: vars.color + \"e6\" },\n          { size: vmin * 2, color: \"rgba(224, 231, 255, 0.9)\" },\n          { size: vmin * 4, color: \"rgba(199, 210, 254, 0.3)\" },\n        ];\n        const variantOf = function (particle) {\n          return variants[Math.floor(particle.seed * variants.length)];\n        };\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"spawner-0\",\n            rate: 1,\n            startFrame: 200,\n            position: { x: view.width / 2, y: -200 * (view.height / 1080) },\n            area: { width: view.width, height: 0 },\n            lifespan: 200,\n          }],\n          behaviors: [\n            { id: \"gravity\", handler: hyperbits.createGravity({ y: 0.1 }) },\n            { id: \"wiggle\", handler: hyperbits.createWiggle(1, 0.5) },\n            { id: \"wind\", handler: function (particle) { particle.velocity.x += 0.01; } },\n            { id: \"fade\", handler: function (particle, age) { particle.opacity = Math.min(1, Math.max(0, age / particle.lifespan)); } },\n          ],\n        });\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.bind(timeline, canvas, simulator, {\n          shape: \"glow\",\n          size: function (particle) { return variantOf(particle).size * 0.7 * Math.SQRT2; },\n          color: function (particle) { return variantOf(particle).color; },\n          offset: function (particle) { const size = variantOf(particle).size; return { x: size / 2, y: size / 2 }; },\n        });\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"particles-snow\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
