    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"First word\",\"default\":\"Control\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .step {\n        color: #fcc192;\n        font-weight: 700;\n        white-space: nowrap;\n        font-size: 8vmin;\n        opacity: 0;\n      }\n      .panel {\n        background-color: #ffffff;\n        color: #000000;\n        padding: 1vmin 4vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"3d-basic\"\n      data-start=\"0\"\n      data-duration=\"5\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"5\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n\n        function heading(text, className) {\n          const node = document.createElement(\"h1\");\n          node.className = className || \"step\";\n          node.textContent = text;\n          node.style.fontSize = view.vmin * 8 + \"px\";\n          node.style.opacity = \"0\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          return node;\n        }\n\n        const one = heading(String(vars.text));\n        one.style.color = vars.color;\n        const two = heading(\"Camera\", \"step panel\");\n        two.style.padding = view.vmin * 1 + \"px \" + view.vmin * 4 + \"px\";\n        const three = heading(\"Action\");\n        three.style.color = vars.color;\n\n        const stepDuration = 50 / 30;\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1000,\n          transitionDuration: stepDuration,\n          stepDuration: stepDuration,\n          easing: \"easeInOutCubic\",\n          steps: [\n            { id: \"1\", x: 0, y: 0, z: 0, element: one },\n            { id: \"2\", x: 0, y: view.vmin * 10, z: view.vmin * 200, element: two },\n            { id: \"3\", x: 0, y: view.vmin * 20, z: view.vmin * 400, element: three },\n          ],\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        [one, two, three].forEach(function (node, index) {\n          const enterTime = index * stepDuration;\n          timeline.fromTo(node, { opacity: 0 }, { opacity: 1, duration: 1, ease: \"none\" }, enterTime);\n          timeline.to(node, { opacity: 0, duration: 1, ease: \"none\" }, enterTime + stepDuration);\n        });\n        timeline.to({}, { duration: 5 }, 0);\n        registerTimeline(\"3d-basic\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
