    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Card color\",\"default\":\"#f6a45c\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #stack {\n        position: relative;\n        transform-style: preserve-3d;\n        z-index: 1;\n      }\n      .card-wrap {\n        position: absolute;\n        inset: 0;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        transform-style: preserve-3d;\n      }\n      .card {\n        width: 100%;\n        height: 100%;\n        border-radius: 24px;\n        border: 4px solid rgba(255, 255, 255, 0.1);\n        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        color: #fcc192;\n        font-weight: 700;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"card-stack\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1080\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"stack\" class=\"clip\" data-start=\"0\" data-duration=\"4\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const stack = document.getElementById(\"stack\");\n        const cardWidth = vmin * 30;\n        const cardHeight = cardWidth * 1.5;\n        stack.style.width = cardWidth + \"px\";\n        stack.style.height = cardHeight + \"px\";\n        const count = 8;\n        const wraps = [];\n        for (let index = 0; index < count; index += 1) {\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"card-wrap\";\n          wrap.style.zIndex = String(-index);\n          wrap.setAttribute(\"data-layout-allow-overlap\", \"\");\n          wrap.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const card = document.createElement(\"div\");\n          card.className = \"card\";\n          card.style.backgroundColor = index % 2 === 0 ? vars.color : \"#68431e\";\n          card.style.borderRadius = unit * 24 + \"px\";\n          card.style.borderWidth = unit * 4 + \"px\";\n          card.style.fontSize = cardWidth * 0.4 + \"px\";\n          const angle = (index - (count - 1) / 2) * 8;\n          const xOffset = (index - (count - 1) / 2) * 60 * unit;\n          card.style.transform = \"translateZ(\" + index * -10 * unit + \"px) translateX(\" + xOffset + \"px) rotateZ(\" + angle + \"deg)\";\n          card.textContent = String(index + 1);\n          wrap.append(card);\n          stack.append(wrap);\n          wraps.push(wrap);\n        }\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(wraps, { y: [800 * unit, 0], duration: 50 / 30, stagger: 3 / 30, ease: \"spring\", at: 0 }, timeline);\n        timeline.to({}, { duration: 4 }, 0);\n        registerTimeline(\"card-stack\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
