    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"message\",\"type\":\"string\",\"label\":\"First message\",\"default\":\"Hey, did the render finish?\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"My bubble color\",\"default\":\"#ec8b49\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1920\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1920px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #thread {\n        position: relative;\n        z-index: 1;\n        width: 100%;\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        justify-content: center;\n        font-weight: 700;\n      }\n      .msg {\n        display: flex;\n        align-items: flex-end;\n      }\n      .msg.me,\n      .msg.me .inner {\n        flex-direction: row-reverse;\n      }\n      .inner {\n        display: flex;\n        align-items: flex-end;\n      }\n      .avatar {\n        border-radius: 50%;\n        flex-shrink: 0;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        font-weight: 700;\n      }\n      .bubble {\n        color: #ffffff;\n        line-height: 1.3;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"chat-conversation\"\n      data-start=\"0\"\n      data-duration=\"5\"\n      data-width=\"1080\"\n      data-height=\"1920\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"5\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"thread\" class=\"clip\" data-start=\"0\" data-duration=\"5\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const thread = document.getElementById(\"thread\");\n        const messages = [\n          { from: \"them\", text: String(vars.message) },\n          { from: \"me\", text: \"Yep, 4K in under two minutes.\" },\n          { from: \"them\", text: \"No way. What did you change?\" },\n          { from: \"me\", text: \"Switched the intro to hyperbits.\" },\n          { from: \"me\", text: \"Staggered motion, zero manual keyframes.\" },\n          { from: \"them\", text: \"Okay, sending you the next brief now.\" },\n        ];\n        const bubbleFont = vmin * 4;\n        const maxBubbleWidth = vmin * 66;\n        const avatarSize = vmin * 6;\n        const startDelay = 10;\n        const stagger = 20;\n        thread.style.gap = vmin * 2.2 + \"px\";\n        thread.style.padding = \"0 \" + vmin * 6 + \"px\";\n        const timeline = gsap.timeline({ paused: true });\n        messages.forEach(function (message, index) {\n          const isMe = message.from === \"me\";\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"msg \" + (isMe ? \"me\" : \"them\");\n          wrap.style.gap = vmin * 1.5 + \"px\";\n          const inner = document.createElement(\"div\");\n          inner.className = \"inner\";\n          inner.style.gap = vmin * 1.5 + \"px\";\n          inner.style.transformOrigin = isMe ? \"bottom right\" : \"bottom left\";\n          const avatar = document.createElement(\"div\");\n          avatar.className = \"avatar\";\n          avatar.style.width = avatarSize + \"px\";\n          avatar.style.height = avatarSize + \"px\";\n          avatar.style.fontSize = avatarSize * 0.42 + \"px\";\n          avatar.style.color = isMe ? vars.background : \"#ffffff\";\n          avatar.style.backgroundColor = isMe ? \"#fcc192\" : \"#343331\";\n          avatar.textContent = isMe ? \"ME\" : \"AL\";\n          const bubble = document.createElement(\"div\");\n          bubble.className = \"bubble\";\n          bubble.textContent = message.text;\n          bubble.style.maxWidth = maxBubbleWidth + \"px\";\n          bubble.style.padding = vmin * 2.2 + \"px \" + vmin * 3.2 + \"px\";\n          bubble.style.borderRadius = vmin * 4 + \"px\";\n          bubble.style.borderBottomRightRadius = (isMe ? vmin * 1 : vmin * 4) + \"px\";\n          bubble.style.borderBottomLeftRadius = (isMe ? vmin * 4 : vmin * 1) + \"px\";\n          bubble.style.backgroundColor = isMe ? vars.color : \"#343331\";\n          bubble.style.fontSize = bubbleFont + \"px\";\n          bubble.style.boxShadow = \"0 \" + vmin * 0.6 + \"px \" + vmin * 2 + \"px rgba(0, 0, 0, 0.35)\";\n          inner.append(avatar, bubble);\n          wrap.append(inner);\n          thread.append(wrap);\n          timeline.fromTo(\n            inner,\n            { scale: 0.4, y: vmin * 4, opacity: 0 },\n            { scale: 1, y: 0, opacity: 1, duration: 22 / 30, ease: hyperbits.Easing.spring },\n            (startDelay + index * stagger) / 30,\n          );\n        });\n        timeline.to({}, { duration: 5 }, 0);\n        registerTimeline(\"chat-conversation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
