    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Tile outline\",\"default\":\"#100f0f\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 900;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-900-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        overflow: hidden;\n      }\n      #mosaic {\n        position: relative;\n        transform-style: preserve-3d;\n        z-index: 1;\n      }\n      .tile-wrap {\n        position: absolute;\n        transform-style: preserve-3d;\n      }\n      .tile {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        overflow: hidden;\n        position: relative;\n      }\n      .tile img {\n        width: 100%;\n        height: 100%;\n        object-fit: cover;\n        position: absolute;\n        inset: 0;\n      }\n      .symbol {\n        font-weight: 900;\n        color: #ffffff;\n        text-shadow: 0 0 5px #000000;\n        line-height: 1;\n        position: relative;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"fracture-reassemble\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1080\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"mosaic\" class=\"clip\" data-start=\"0\" data-duration=\"6\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const mosaic = document.getElementById(\"mosaic\");\n        const ROWS = 5;\n        const COLS = 5;\n        const CENTER_ROW = 2;\n        const SYMBOLS = [\"\\u25C8\", \"\\u25C9\", \"\\u25CE\", \"\\u25CD\", \"\\u25CC\"];\n        const gap = vmin * 1.2;\n        const tileSize = vmin * 14;\n        mosaic.style.width = COLS * tileSize + (COLS - 1) * gap + \"px\";\n        mosaic.style.height = ROWS * tileSize + (ROWS - 1) * gap + \"px\";\n        const ease = hyperbits.Easing.easeInOutCubic;\n        const hold = hyperbits.hold(60);\n        const tiles = [];\n        for (let index = 0; index < ROWS * COLS; index += 1) {\n          const row = Math.floor(index / COLS);\n          const col = index % COLS;\n          const wrap = document.createElement(\"div\");\n          wrap.className = \"tile-wrap\";\n          wrap.style.left = col * (tileSize + gap) + \"px\";\n          wrap.style.top = row * (tileSize + gap) + \"px\";\n          wrap.style.width = tileSize + \"px\";\n          wrap.style.height = tileSize + \"px\";\n          wrap.style.perspective = vmin * 100 + \"px\";\n          wrap.setAttribute(\"data-layout-allow-overlap\", \"\");\n          wrap.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const tile = document.createElement(\"div\");\n          tile.className = \"tile\";\n          tile.style.borderRadius = vmin * 1.5 + \"px\";\n          tile.style.boxShadow = \"0 0 0 \" + vmin * 0.25 + \"px \" + vars.color;\n          const image = document.createElement(\"img\");\n          image.src = \"https://picsum.photos/seed/\" + (index + 1) + \"/\" + Math.round(tileSize) + \"/\" + Math.round(tileSize);\n          image.alt = \"\";\n          tile.append(image);\n          if (row === CENTER_ROW) {\n            const symbol = document.createElement(\"span\");\n            symbol.className = \"symbol\";\n            symbol.textContent = SYMBOLS[col];\n            symbol.style.fontSize = tileSize * 0.55 + \"px\";\n            tile.append(symbol);\n          }\n          wrap.append(tile);\n          mosaic.append(wrap);\n          tiles.push({\n            element: tile,\n            delay: (Math.abs(row - 2) + Math.abs(col - 2)) * 4,\n            dx: hyperbits.randomFloat(\"frac-x-\" + index, -vmin * 80, vmin * 80),\n            dy: hyperbits.randomFloat(\"frac-y-\" + index, -vmin * 80, vmin * 80),\n            dz: hyperbits.randomFloat(\"frac-z-\" + index, -vmin * 120, vmin * 20),\n            rx: hyperbits.randomFloat(\"frac-rx-\" + index, -180, 180),\n            ry: hyperbits.randomFloat(\"frac-ry-\" + index, -180, 180),\n            rz: hyperbits.randomFloat(\"frac-rz-\" + index, -90, 90),\n          });\n        }\n        const proxy = { frame: 0 };\n        function render() {\n          const frame = proxy.frame;\n          for (const tile of tiles) {\n            const progress = Math.min(1, Math.max(0, (frame - tile.delay) / 170));\n            const value = function (from) {\n              return hyperbits.interpolateKeyframes([from, 0, hold, from], progress, ease, 170);\n            };\n            const opacity = hyperbits.interpolateKeyframes([0, 1, hold, 0], progress, ease, 170);\n            tile.element.style.transform =\n              \"translateX(\" + value(tile.dx) + \"px) translateY(\" + value(tile.dy) + \"px) translateZ(\" + value(tile.dz) + \"px)\" +\n              \" rotateX(\" + value(tile.rx) + \"deg) rotateY(\" + value(tile.ry) + \"deg) rotateZ(\" + value(tile.rz) + \"deg)\";\n            tile.element.style.opacity = String(opacity);\n          }\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { frame: 180, duration: 6, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"fracture-reassemble\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
