    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Icon color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#09090b\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 500;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-500-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #09090b;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #09090b;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #list-outer {\n        position: relative;\n        z-index: 1;\n      }\n      #list {\n        display: flex;\n        flex-direction: column;\n      }\n      .item {\n        width: 100%;\n        background-color: #27272a;\n        display: flex;\n        align-items: center;\n        box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);\n      }\n      .icon {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      .title {\n        color: #f4f4f5;\n        font-weight: 500;\n        flex: 1;\n      }\n      .dot {\n        border-radius: 50%;\n        background-color: #52525b;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"list-reveal\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1080\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#09090b\"></div>\n      <div id=\"list-outer\" class=\"clip\" data-start=\"0\" data-duration=\"3\"><div id=\"list\"></div></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const outer = document.getElementById(\"list-outer\");\n        const list = document.getElementById(\"list\");\n        const items = [\n          { title: \"Dashboard\", path: \"M3 13h8V3H3v10zm10 8h8V3h-8v18zM3 21h8v-6H3v6z\" },\n          { title: \"Analytics\", path: \"M3 17l6-6 4 4 8-8\" },\n          { title: \"Settings\", path: \"M12 8a4 4 0 100 8 4 4 0 000-8z\" },\n          { title: \"Profile\", path: \"M12 12a4 4 0 100-8 4 4 0 000 8zm0 2c-4 0-8 2-8 6v2h16v-2c0-4-4-6-8-6z\" },\n          { title: \"Messages\", path: \"M4 4h16v12H7l-3 3V4z\" },\n          { title: \"Notifications\", path: \"M12 22a2 2 0 002-2H10a2 2 0 002 2zm6-6V11a6 6 0 10-12 0v5L4 18v1h16v-1l-2-2z\" },\n        ];\n        const itemWidth = Math.min(view.width * 0.8, 600 * unit);\n        const itemHeight = 80 * unit;\n        list.style.width = itemWidth + \"px\";\n        list.style.gap = 16 * unit + \"px\";\n        for (const item of items) {\n          const row = document.createElement(\"div\");\n          row.className = \"item\";\n          row.style.height = itemHeight + \"px\";\n          row.style.borderRadius = 12 * unit + \"px\";\n          row.style.padding = \"0 \" + 24 * unit + \"px\";\n          row.style.gap = 16 * unit + \"px\";\n          const icon = document.createElement(\"div\");\n          icon.className = \"icon\";\n          icon.style.width = 24 * unit + \"px\";\n          icon.style.height = 24 * unit + \"px\";\n          const svg = document.createElementNS(\"http://www.w3.org/2000/svg\", \"svg\");\n          svg.setAttribute(\"width\", String(24 * unit));\n          svg.setAttribute(\"height\", String(24 * unit));\n          svg.setAttribute(\"viewBox\", \"0 0 24 24\");\n          svg.setAttribute(\"fill\", vars.color);\n          const path = document.createElementNS(\"http://www.w3.org/2000/svg\", \"path\");\n          path.setAttribute(\"d\", item.path);\n          svg.append(path);\n          icon.append(svg);\n          const title = document.createElement(\"div\");\n          title.className = \"title\";\n          title.textContent = item.title;\n          title.style.fontSize = 20 * unit + \"px\";\n          const dot = document.createElement(\"div\");\n          dot.className = \"dot\";\n          dot.style.width = 8 * unit + \"px\";\n          dot.style.height = 8 * unit + \"px\";\n          row.append(icon, title, dot);\n          list.append(row);\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(list, { y: 200 * unit }, { y: -100 * unit, duration: 1, ease: hyperbits.Easing.easeInOutCubic }, 0);\n        hyperbits.stagger(list.children, { y: [50 * unit, 0], opacity: [0, 1], scale: [0.9, 1], duration: 40 / 30, stagger: 3 / 30, ease: \"easeOutCubic\", at: 0 }, timeline);\n        timeline.to({}, { duration: 3 }, 0);\n        registerTimeline(\"list-reveal\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
