    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"name\",\"type\":\"string\",\"label\":\"Name\",\"default\":\"Ada Lovelace\"},{\"id\":\"title\",\"type\":\"string\",\"label\":\"Title\",\"default\":\"Analytical Engine Programmer\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#ec8b49\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#1c1b1a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 500;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-500-normal.woff2) format(\"woff2\");\n      }\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #1c1b1a;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #1c1b1a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #card {\n        position: absolute;\n        display: flex;\n        align-items: stretch;\n        z-index: 1;\n        color: #ffffff;\n      }\n      #bar {\n        transform-origin: center top;\n      }\n      #copy {\n        display: flex;\n        flex-direction: column;\n        justify-content: center;\n      }\n      #name {\n        font-weight: 700;\n        line-height: 1.05;\n      }\n      #role-line {\n        font-size: 5vw;\n      }\n      #role {\n        display: inline-flex;\n        align-items: center;\n        font-weight: 500;\n        color: #fcc192;\n        text-transform: uppercase;\n      }\n      #role-dot {\n        border-radius: 50%;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"lower-third\"\n      data-start=\"0\"\n      data-duration=\"5\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"5\" style=\"position:absolute;inset:0;background-color:#1c1b1a\"></div>\n      <div id=\"card\" class=\"clip\" data-start=\"0\" data-duration=\"5\">\n        <div id=\"bar\"></div>\n        <div id=\"copy\">\n          <div id=\"name\">Ada Lovelace</div>\n          <div id=\"role-line\"><div id=\"role\"><span id=\"role-dot\"></span><span id=\"role-text\">Analytical Engine Programmer</span></div></div>\n        </div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const card = document.getElementById(\"card\");\n        const bar = document.getElementById(\"bar\");\n        const copy = document.getElementById(\"copy\");\n        const nameEl = document.getElementById(\"name\");\n        const role = document.getElementById(\"role\");\n        document.getElementById(\"role-line\").style.fontSize = view.vw * 5 + \"px\";\n        const roleDot = document.getElementById(\"role-dot\");\n        const roleText = document.getElementById(\"role-text\");\n        bg.style.backgroundImage = \"radial-gradient(circle at 70% 30%, #343331 0%, \" + vars.background + \" 60%)\";\n        nameEl.textContent = vars.name;\n        roleText.textContent = vars.title;\n        const total = 150;\n        const enter = 25;\n        const exit = 20;\n        const holdFrames = total - enter - exit;\n        const barWidth = vmin * 1.6;\n        const cardHeight = vmin * 18;\n        const shift = vmin * 6;\n        card.style.left = view.vw * 6 + \"px\";\n        card.style.bottom = view.vh * 10 + \"px\";\n        bar.style.width = barWidth + \"px\";\n        bar.style.minHeight = cardHeight + \"px\";\n        bar.style.borderRadius = barWidth + \"px\";\n        bar.style.backgroundColor = vars.color;\n        copy.style.gap = vmin * 1.2 + \"px\";\n        copy.style.padding = vmin * 1.5 + \"px 0 \" + vmin * 1.5 + \"px \" + vmin * 3 + \"px\";\n        nameEl.style.fontSize = vmin * 6.5 + \"px\";\n        nameEl.style.letterSpacing = -vmin * 0.1 + \"px\";\n        role.style.gap = vmin * 1.5 + \"px\";\n        role.style.fontSize = vmin * 2.8 + \"px\";\n        role.style.letterSpacing = vmin * 0.25 + \"px\";\n        roleDot.style.width = vmin + \"px\";\n        roleDot.style.height = vmin + \"px\";\n        roleDot.style.backgroundColor = vars.color;\n        const ease = hyperbits.Easing;\n        function holdMotion(element, from, to, delay, duration, holdLength, easing) {\n          const segment = (duration - holdLength) / 2 / 30;\n          const start = delay / 30;\n          const target = Object.assign({ duration: segment, ease: easing }, to);\n          timeline.fromTo(element, from, target, start);\n          const back = Object.assign({ duration: segment, ease: easing }, from);\n          timeline.to(element, back, start + segment + holdLength / 30);\n        }\n        const timeline = gsap.timeline({ paused: true });\n        holdMotion(bar, { scaleY: 0 }, { scaleY: 1 }, 0, total, holdFrames, ease.easeInOutCubic);\n        holdMotion(nameEl, { x: -shift, opacity: 0 }, { x: 0, opacity: 1 }, 6, total - 6, holdFrames - 8, ease.easeOutCubic);\n        holdMotion(role, { x: -shift, opacity: 0 }, { x: 0, opacity: 1 }, 12, total - 12, holdFrames - 16, ease.easeOutCubic);\n        timeline.to({}, { duration: 5 }, 0);\n        registerTimeline(\"lower-third\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
