    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Accent\",\"default\":\"#3b82f6\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#0f172a\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #0f172a;\n        --fg: #f8fafc;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #0f172a;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #row {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        gap: 2.963vmin;\n        position: relative;\n        z-index: 1;\n      }\n      .box {\n        width: 13.889vmin;\n        height: 13.889vmin;\n        border-radius: 1.111vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"staggered-fade-in\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#0f172a\"></div>\n      <div id=\"row\" class=\"clip\" data-start=\"0\" data-duration=\"3\">\n        <div class=\"box\" data-color=\"#3b82f6\"></div>\n        <div class=\"box\" data-color=\"#ef4444\"></div>\n        <div class=\"box\" data-color=\"#10b981\"></div>\n        <div class=\"box\" data-color=\"#f59e0b\"></div>\n        <div class=\"box\" data-color=\"#8b5cf6\"></div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const row = document.getElementById(\"row\");\n        const view = hyperbits.viewport(root);\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        row.style.gap = unit * 32 + \"px\";\n        const boxes = Array.from(row.querySelectorAll(\".box\"));\n        for (let index = 0; index < boxes.length; index += 1) {\n          const box = boxes[index];\n          box.style.width = unit * 150 + \"px\";\n          box.style.height = unit * 150 + \"px\";\n          box.style.borderRadius = unit * 12 + \"px\";\n          box.style.backgroundColor = index === 0 ? vars.color : box.getAttribute(\"data-color\");\n        }\n        const timeline = gsap.timeline({ paused: true });\n        hyperbits.stagger(boxes, { opacity: [0, 1], y: [unit * 100, 0], duration: 1, stagger: 5 / 30, ease: \"easeOutCubic\" }, timeline);\n        timeline.to({}, { duration: 3 }, 0);\n        registerTimeline(\"staggered-fade-in\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
