    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"title\",\"type\":\"string\",\"label\":\"Title\",\"default\":\"Weekly commits by language\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Bar color\",\"default\":\"#ec8b49\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 500;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-500-normal.woff2) format(\"woff2\");\n      }\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #chart-wrap {\n        position: relative;\n        z-index: 1;\n        width: 100%;\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        color: #ffffff;\n      }\n      #heading {\n        font-weight: 700;\n        font-size: 4.5vmin;\n      }\n      #rows {\n        display: flex;\n        flex-direction: column;\n      }\n      .row {\n        display: flex;\n        align-items: center;\n      }\n      .label-wrap {\n        display: flex;\n        justify-content: flex-end;\n      }\n      .label {\n        font-weight: 500;\n        color: #fcc192;\n        display: inline-block;\n      }\n      .track {\n        display: flex;\n        align-items: center;\n      }\n      .bar {\n        transform-origin: left center;\n        background: linear-gradient(90deg, #ec8b49 0%, #fcc192 100%);\n      }\n      .count {\n        display: inline-flex;\n        align-items: center;\n        font-weight: 700;\n        font-variant-numeric: tabular-nums;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"bar-chart\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"chart-wrap\" class=\"clip\" data-start=\"0\" data-duration=\"4\">\n        <div id=\"heading-wrap\"><div id=\"heading\">Weekly commits by language</div></div>\n        <div id=\"rows\"></div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        bg.style.backgroundColor = vars.background;\n        const heading = document.getElementById(\"heading\");\n        const rows = document.getElementById(\"rows\");\n        heading.textContent = vars.title;\n        const data = [\n          { label: \"TypeScript\", value: 84 },\n          { label: \"Rust\", value: 67 },\n          { label: \"Python\", value: 58 },\n          { label: \"Go\", value: 41 },\n          { label: \"Zig\", value: 23 },\n        ];\n        const maxValue = Math.max.apply(null, data.map(function (row) { return row.value; }));\n        const chartWidth = view.vw * 60;\n        const labelWidth = view.vw * 14;\n        const barHeight = vmin * 7;\n        const gap = vmin * 3;\n        heading.style.fontSize = vmin * 4.5 + \"px\";\n        heading.style.marginBottom = gap * 1.5 + \"px\";\n        heading.style.marginLeft = labelWidth + \"px\";\n        rows.style.gap = gap + \"px\";\n        const timeline = gsap.timeline({ paused: true });\n        timeline.fromTo(heading, { opacity: 0, y: vmin * 2 }, { opacity: 1, y: 0, duration: 1, ease: hyperbits.Easing.easeOutCubic }, 0);\n        data.forEach(function (row, index) {\n          const delay = (15 + index * 8) / 30;\n          const line = document.createElement(\"div\");\n          line.className = \"row\";\n          line.style.height = barHeight + \"px\";\n          line.style.gap = vmin * 2 + \"px\";\n          const labelWrap = document.createElement(\"div\");\n          labelWrap.className = \"label-wrap\";\n          labelWrap.style.width = labelWidth + \"px\";\n          const label = document.createElement(\"span\");\n          label.className = \"label\";\n          label.textContent = row.label;\n          label.style.fontSize = vmin * 3 + \"px\";\n          labelWrap.append(label);\n          const track = document.createElement(\"div\");\n          track.className = \"track\";\n          track.style.width = chartWidth + \"px\";\n          track.style.gap = vmin * 2 + \"px\";\n          const bar = document.createElement(\"div\");\n          bar.className = \"bar\";\n          bar.style.width = (row.value / maxValue) * chartWidth + \"px\";\n          bar.style.height = barHeight + \"px\";\n          bar.style.borderRadius = vmin + \"px\";\n          bar.style.background = \"linear-gradient(90deg, \" + vars.color + \" 0%, #fcc192 100%)\";\n          const countWrap = document.createElement(\"div\");\n          const count = document.createElement(\"span\");\n          count.className = \"count\";\n          count.style.fontSize = vmin * 3.2 + \"px\";\n          countWrap.append(count);\n          const counter = hyperbits.createCounter(count, {});\n          track.append(bar, countWrap);\n          line.append(labelWrap, track);\n          rows.append(line);\n          timeline.fromTo(label, { opacity: 0, x: -vmin * 3 }, { opacity: 1, x: 0, duration: 25 / 30, ease: hyperbits.Easing.easeOutCubic }, delay);\n          timeline.fromTo(bar, { scaleX: 0 }, { scaleX: 1, duration: 45 / 30, ease: hyperbits.Easing.easeOutQuart }, delay);\n          timeline.fromTo(count, { opacity: 0 }, { opacity: 1, duration: 15 / 30, ease: \"none\" }, delay);\n          timeline.fromTo(counter.proxy, { value: 0 }, { value: row.value, duration: 45 / 30, ease: hyperbits.Easing.easeOutQuart, onUpdate: counter.apply }, delay);\n        });\n        timeline.to({}, { duration: 4 }, 0);\n        registerTimeline(\"bar-chart\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
