    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Function color\",\"default\":\"#dcdcaa\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #panel {\n        position: relative;\n        z-index: 1;\n      }\n      .hyperbits-code {\n        color: #9cdcfe;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        font-variant-ligatures: none;\n        line-height: 1.5;\n      }\n      .hyperbits-code-line {\n        position: relative;\n        width: 100%;\n      }\n      .hyperbits-code-gutter {\n        display: inline-block;\n        width: 2.5em;\n        text-align: right;\n        padding-right: 1em;\n        opacity: 0.5;\n        color: #666666;\n        flex-shrink: 0;\n      }\n      .token.keyword,\n      .token.builtin {\n        color: #569cd6;\n      }\n      .token.function {\n        color: #dcdcaa;\n      }\n      .token.string,\n      .token.attr-value {\n        color: #ce9178;\n      }\n      .token.punctuation,\n      .token.operator {\n        color: #d4d4d4;\n      }\n      .token.number {\n        color: #b5cea8;\n      }\n      .token.comment {\n        color: #6a9955;\n      }\n      .token.class-name {\n        color: #4ec9b0;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"basic-code-block\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"panel\" class=\"clip\" data-start=\"0\" data-duration=\"4\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const panel = document.getElementById(\"panel\");\n        const fontSize = view.width * 0.025;\n        panel.style.fontSize = fontSize + \"px\";\n        panel.style.padding = fontSize + \"px\";\n        const code = \"function hello() {\\n  console.log(\\\"Hello World\\\");\\n  return true;\\n}\";\n        const block = hyperbits.createCodeBlock(panel, { code: code, language: \"typescript\", showLineNumbers: true });\n        block.style.fontSize = fontSize + \"px\";\n        hyperbits.codeLines(block).forEach(function (line) {\n          line.style.display = \"flex\";\n          const content = line.querySelector(\".hyperbits-code-content\");\n          content.style.display = \"block\";\n          content.style.width = \"100%\";\n        });\n        const functions = panel.querySelectorAll(\".token.function\");\n        for (let index = 0; index < functions.length; index += 1) {\n          functions[index].style.color = vars.color;\n        }\n        const lines = hyperbits.codeLines(block);\n        const timeline = gsap.timeline({ paused: true });\n        lines.forEach(function (line, index) {\n          timeline.fromTo(line, { opacity: 0, y: unit * 10 }, { opacity: 1, y: 0, duration: 1, ease: \"none\" }, (index * 5) / 30);\n        });\n        timeline.to({}, { duration: 4 }, 0);\n        registerTimeline(\"basic-code-block\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
