    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"target\",\"type\":\"number\",\"label\":\"Target value\",\"default\":1000},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 900;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-900-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #stage {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n      #value {\n        position: relative;\n        z-index: 2;\n        display: inline-flex;\n        align-items: center;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 900;\n        font-size: 15vmin;\n        color: #fcc192;\n        text-shadow: 0 0 4vmin #fcc192;\n        letter-spacing: 0.5vmin;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"counter-confetti\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"stage\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;width:100%;height:100%;z-index:1\"></canvas>\n      <div id=\"value\" class=\"clip\" data-start=\"0\" data-duration=\"6\">0</div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        bg.style.backgroundColor = vars.background;\n        const canvas = document.getElementById(\"stage\");\n        const valueEl = document.getElementById(\"value\");\n        valueEl.style.color = vars.color;\n        valueEl.style.fontSize = vmin * 15 + \"px\";\n        valueEl.style.textShadow = \"0 0 \" + vmin * 4 + \"px \" + vars.color;\n        valueEl.style.letterSpacing = vmin * 0.5 + \"px\";\n        canvas.width = view.width;\n        canvas.height = view.height;\n        const counter = hyperbits.createCounter(valueEl, { decimals: 0 });\n        const target = Number(vars.target) || 1000;\n        const confettiColors = [\"#FF6B6B\", \"#FFD93D\", \"#6BCB77\", \"#4D96FF\", \"#C084FC\", \"#FF8FA3\", \"#36D399\", \"#FBBD23\"];\n        const confettiStart = 85;\n        const pieceWidth = vmin * 3;\n        const anchor = { x: pieceWidth / 2, y: (pieceWidth * 0.6) / 2 };\n        const sideArea = { width: 0, height: view.height * 0.3 };\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [\n            {\n              id: \"spawner-0\",\n              burst: 40,\n              delayFrame: confettiStart,\n              position: { x: -view.width * 0.05 + anchor.x, y: view.height * 0.5 + anchor.y },\n              area: sideArea,\n              velocity: { x: view.width * 0.04, y: -view.height * 0.02, varianceX: view.width * 0.015, varianceY: view.height * 0.03 },\n              lifespan: 120,\n              max: 40,\n            },\n            {\n              id: \"spawner-1\",\n              burst: 40,\n              delayFrame: confettiStart,\n              position: { x: view.width * 1.05 + anchor.x, y: view.height * 0.5 + anchor.y },\n              area: sideArea,\n              velocity: { x: -view.width * 0.04, y: -view.height * 0.02, varianceX: view.width * 0.015, varianceY: view.height * 0.03 },\n              lifespan: 120,\n              max: 40,\n            },\n            {\n              id: \"spawner-2\",\n              burst: 30,\n              delayFrame: confettiStart,\n              position: { x: view.width * 0.5 + anchor.x, y: view.height * 1.1 + anchor.y },\n              area: { width: view.width * 0.6, height: 0 },\n              velocity: { x: 0, y: -view.height * 0.06, varianceX: view.width * 0.02, varianceY: view.height * 0.015 },\n              lifespan: 120,\n              max: 30,\n            },\n          ],\n          behaviors: [\n            { id: \"gravity\", handler: hyperbits.createGravity({ y: 0.3 }) },\n            { id: \"spin\", handler: function (particle) { particle.rotation += particle.velocity.x * 0.8; } },\n            { id: \"drag\", handler: hyperbits.createDrag(0.98) },\n            { id: \"fade\", handler: hyperbits.createOpacityOverLife([1, 0]) },\n          ],\n        });\n        const proxy = { progress: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          progress: 1,\n          duration: 3,\n          ease: \"none\",\n          onUpdate: function () {\n            const ease = hyperbits.Easing.easeOutQuart;\n            counter.proxy.value = hyperbits.interpolateKeyframes([0, target], proxy.progress, ease);\n            counter.apply();\n            const scale = hyperbits.interpolateKeyframes([0.2, 1.3, 1.3, 1], proxy.progress, ease);\n            const opacity = hyperbits.interpolateKeyframes([0, 1], proxy.progress, ease);\n            valueEl.style.transform = \"scale(\" + scale + \")\";\n            valueEl.style.opacity = String(opacity);\n          },\n        }, 0);\n        hyperbits.bind(timeline, canvas, simulator, {\n          shape: \"rect\",\n          size: pieceWidth,\n          cornerRadius: vmin * 0.45,\n          glow: 0,\n          color: function (particle) {\n            return confettiColors[Math.floor(particle.seed * confettiColors.length)];\n          },\n        });\n        timeline.to({}, { duration: 6 }, 0);\n        registerTimeline(\"counter-confetti\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
