    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"headline\",\"type\":\"string\",\"label\":\"Headline\",\"default\":\"DEPTH\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"Face\",\"default\":\"#f2f0e5\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"Extrusion\",\"default\":\"#ec8b49\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 900;\n        font-display: block;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-900-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #f2f0e5;\n        --accent: #ec8b49;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        perspective: 2200px;\n      }\n      #word {\n        position: absolute;\n        left: 50%;\n        top: 50%;\n        display: flex;\n        transform-style: preserve-3d;\n      }\n      .letter {\n        position: relative;\n        transform-style: preserve-3d;\n      }\n      .layer {\n        position: absolute;\n        left: 0;\n        top: 0;\n        font-family: \"Geist Sans\", ui-sans-serif, system-ui, sans-serif;\n        font-weight: 900;\n        line-height: 1;\n        white-space: pre;\n      }\n      .ghost {\n        visibility: hidden;\n        font-family: \"Geist Sans\", ui-sans-serif, system-ui, sans-serif;\n        font-weight: 900;\n        line-height: 1;\n        white-space: pre;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"extruded-type\"\n      data-start=\"0\"\n      data-duration=\"7\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"7\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"scene\" class=\"clip\" data-start=\"0\" data-duration=\"7\"><div id=\"word\"></div></div>\n    </div>\n    <script>\n      (function () {\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n        function channels(color) {\n          const parts = hyperbits.mixOklch(String(color), String(color), 0, \"rgb(0, 0, 0)\").match(/[0-9.]+/g) || [0, 0, 0];\n          return parts.slice(0, 3).map(Number);\n        }\n        function rgba(rgb, alpha) {\n          return \"rgba(\" + Math.round(rgb[0]) + \", \" + Math.round(rgb[1]) + \", \" + Math.round(rgb[2]) + \", \" + Math.min(Math.max(alpha, 0), 1) + \")\";\n        }\n        function mixRgb(from, to, amount) {\n          return [from[0] + (to[0] - from[0]) * amount, from[1] + (to[1] - from[1]) * amount, from[2] + (to[2] - from[2]) * amount];\n        }\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const word = document.getElementById(\"word\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        const duration = 7;\n        const back = channels(vars.background);\n        const fore = channels(vars.foreground);\n        const accent = channels(vars.accent);\n        const text = String(vars.headline).slice(0, 14);\n        const fontSize = Math.min(view.vmin * 30, (view.width * 0.8) / Math.max(1, text.length * 0.68));\n        const layers = 28;\n        const depth = fontSize * 0.32;\n        word.setAttribute(\"aria-label\", text);\n        const letters = Array.from(text).map((character) => {\n          const letter = document.createElement(\"div\");\n          letter.className = \"letter\";\n          const ghost = document.createElement(\"span\");\n          ghost.className = \"ghost\";\n          ghost.textContent = character;\n          ghost.style.fontSize = fontSize + \"px\";\n          letter.append(ghost);\n          for (let layer = layers; layer >= 0; layer -= 1) {\n            const node = document.createElement(\"span\");\n            node.className = \"layer\";\n            node.textContent = character;\n            node.style.fontSize = fontSize + \"px\";\n            const amount = layer / layers;\n            const color = layer === 0 ? fore : mixRgb(mixRgb(accent, fore, 0.18), mixRgb(accent, back, 0.72), amount);\n            node.style.color = rgba(color, 1);\n            node.style.transform = \"translateZ(\" + -amount * depth + \"px)\";\n            letter.append(node);\n          }\n          word.append(letter);\n          return letter;\n        });\n        word.style.transform = \"translate(-50%, -50%)\";\n        const shadow = document.createElement(\"div\");\n        shadow.style.position = \"absolute\";\n        shadow.style.left = \"50%\";\n        shadow.style.top = \"72%\";\n        shadow.style.width = view.width * 0.6 + \"px\";\n        shadow.style.height = view.vmin * 8 + \"px\";\n        shadow.style.marginLeft = -view.width * 0.3 + \"px\";\n        shadow.style.borderRadius = \"50%\";\n        shadow.style.background = \"radial-gradient(closest-side, rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0))\";\n        document.getElementById(\"scene\").prepend(shadow);\n        const proxy = { time: 0 };\n        function render() {\n          const time = proxy.time;\n          letters.forEach((letter, index) => {\n            const start = 0.25 + index * 0.11;\n            const raw = Math.min(1, Math.max(0, (time - start) / 0.9));\n            const eased = 1 - Math.pow(1 - raw, 3) * Math.cos(raw * Math.PI * 1.1);\n            const flip = (1 - eased) * 100;\n            letter.style.transform = \"translateY(\" + (1 - Math.min(1, raw * 1.6)) * fontSize * 0.5 + \"px) rotateX(\" + flip + \"deg)\";\n            letter.style.transformOrigin = \"50% 100% \" + -depth / 2 + \"px\";\n            letter.style.opacity = String(Math.min(1, raw * 4));\n          });\n          const settle = hyperbits.Easing.easeInOutSine(Math.min(1, Math.max(0, (time - 1.2) / 5.8)));\n          const yaw = -28 + settle * 50 + Math.sin(time * 0.7) * 3;\n          const pitch = 14 - settle * 6;\n          word.style.transform = \"translate(-50%, -50%) rotateX(\" + pitch + \"deg) rotateY(\" + yaw + \"deg)\";\n          shadow.style.opacity = String(Math.min(1, time / 1.2) * 0.9);\n          shadow.style.transform = \"scaleX(\" + (0.8 + 0.2 * Math.cos((yaw * Math.PI) / 180)) + \")\";\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: duration, duration: duration, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"extruded-type\", timeline);\n      })();\n    </script>\n  </body>\n</html>\n",
