    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"Text\",\"default\":\"SYSTEM ONLINE\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #title {\n        color: #fcc192;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        font-size: 5vw;\n        white-space: pre;\n        position: relative;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"glitch-in\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <h1 id=\"title\" class=\"clip\" data-start=\"0\" data-duration=\"3\">SYSTEM ONLINE</h1>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const title = document.getElementById(\"title\");\n        const view = hyperbits.viewport(root);\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        title.style.color = vars.color;\n        title.style.fontSize = view.vw * 5 + \"px\";\n        const finalText = String(vars.text);\n        title.setAttribute(\"aria-label\", finalText);\n        const GLITCH_CHARS = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?/~`\";\n        const proxy = { time: 0 };\n        function renderGlitch() {\n          const frame = Math.round(proxy.time * 30);\n          const progress = Math.min(1, Math.max(0, frame / 45));\n          const glitchVal = hyperbits.interpolateKeyframes([1, 0, 0.05, 0], progress);\n          let output = \"\";\n          for (let charIndex = 0; charIndex < finalText.length; charIndex += 1) {\n            const char = finalText[charIndex];\n            if (char === \" \" || char === \"\\n\" || glitchVal <= 0) {\n              output += char;\n            } else if (hyperbits.random(\"glitch-\" + frame + \"-0-\" + charIndex) < glitchVal) {\n              output += GLITCH_CHARS[Math.floor(hyperbits.random(\"char-\" + frame + \"-0-\" + charIndex) * GLITCH_CHARS.length)];\n            } else {\n              output += char;\n            }\n          }\n          title.textContent = output;\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 3, duration: 3, ease: \"none\", onUpdate: renderGlitch }, 0);\n        timeline.fromTo(title, { opacity: 0 }, { opacity: 1, duration: 45 / 30, ease: \"none\" }, 0);\n        renderGlitch();\n        registerTimeline(\"glitch-in\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
