    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Rain color\",\"default\":\"#00FF41\"},{\"id\":\"fontSize\",\"type\":\"number\",\"label\":\"Font size (px at 1080p)\",\"default\":30},{\"id\":\"speed\",\"type\":\"number\",\"label\":\"Speed\",\"default\":1},{\"id\":\"density\",\"type\":\"number\",\"label\":\"Density (0-1)\",\"default\":1},{\"id\":\"streamLength\",\"type\":\"number\",\"label\":\"Stream length\",\"default\":15},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 400;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-400-normal.woff2) format(\"woff2\");\n      }\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #rain {\n        position: absolute;\n        inset: 0;\n        width: 100%;\n        height: 100%;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"matrix-rain\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <canvas id=\"rain\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></canvas>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        bg.style.backgroundColor = vars.background;\n        const canvas = document.getElementById(\"rain\");\n        canvas.setAttribute(\"data-color\", vars.color);\n        canvas.width = view.width;\n        canvas.height = view.height;\n        let context = null;\n        try {\n          context = canvas.getContext(\"2d\");\n        } catch (err) {\n          context = null;\n        }\n        const fontSize = (Number(vars.fontSize) || 30) * (view.height / 1080);\n        const color = String(vars.color);\n        const speed = Number(vars.speed) || 1;\n        const density = Math.min(Math.max(Number(vars.density) || 0, 0), 1);\n        const streamLength = Number(vars.streamLength) || 15;\n        const charset = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz$+-*/=%\\\"'#&_(),.;:?!\\\\|{}<>[]^~\";\n        const cols = Math.floor(view.width / fontSize);\n        const rows = Math.ceil(view.height / fontSize);\n        const effectiveHeight = view.height + streamLength * fontSize;\n        const streams = [];\n        for (let index = 0; index < cols; index += 1) {\n          streams.push({\n            isVisible: hyperbits.random(index) < density,\n            speed: speed * (0.5 + hyperbits.random(index + 1) * 1.5),\n            offset: hyperbits.random(index + 2) * effectiveHeight,\n            seed: index,\n          });\n        }\n        const fontFamily = '\"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace';\n        const proxy = { time: 0 };\n        function draw() {\n          if (!context || typeof context.fillText !== \"function\") return;\n          const frame = Math.round(proxy.time * 30);\n          context.clearRect(0, 0, canvas.width, canvas.height);\n          context.textBaseline = \"top\";\n          for (let colIndex = 0; colIndex < streams.length; colIndex += 1) {\n            const stream = streams[colIndex];\n            if (!stream.isVisible) continue;\n            const headY = (frame * stream.speed * fontSize + stream.offset) % effectiveHeight;\n            for (let row = 0; row < rows; row += 1) {\n              const y = row * fontSize;\n              const distInChars = (headY - y) / fontSize;\n              if (distInChars < 0 || distInChars >= streamLength) continue;\n              const isHead = distInChars < 1;\n              const charSeed = stream.seed * 1000 + row * 100 + Math.floor(frame / 4);\n              const glyph = charset[Math.floor(hyperbits.random(charSeed) * charset.length)];\n              context.globalAlpha = isHead ? 1 : 1 - distInChars / streamLength;\n              context.fillStyle = isHead ? \"#FFFFFF\" : color;\n              context.font = (isHead ? \"bold \" : \"\") + fontSize + \"px \" + fontFamily;\n              context.shadowBlur = isHead ? 8 * (view.height / 1080) : 0;\n              context.shadowColor = isHead ? \"#FFFFFF\" : \"rgba(0, 0, 0, 0)\";\n              context.fillText(glyph, colIndex * fontSize, y);\n            }\n          }\n          context.globalAlpha = 1;\n          context.shadowBlur = 0;\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 10, duration: 10, ease: \"none\", onUpdate: draw }, 0);\n        draw();\n        registerTimeline(\"matrix-rain\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
