    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Function color\",\"default\":\"#dcdcaa\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#1e1e1e\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #1e1e1e;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #1e1e1e;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #panel {\n        position: relative;\n        z-index: 1;\n        width: 80%;\n      }\n      .hyperbits-code {\n        color: #9cdcfe;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        font-variant-ligatures: none;\n        line-height: 1.5;\n      }\n      .hyperbits-code-line {\n        position: relative;\n        width: 100%;\n      }\n      .hyperbits-code-gutter {\n        display: inline-block;\n        width: 2.5em;\n        text-align: right;\n        padding-right: 1em;\n        opacity: 0.5;\n        color: #666666;\n        flex-shrink: 0;\n      }\n      .token.keyword,\n      .token.builtin {\n        color: #569cd6;\n      }\n      .token.function {\n        color: #dcdcaa;\n      }\n      .token.string,\n      .token.attr-value {\n        color: #ce9178;\n      }\n      .token.punctuation,\n      .token.operator {\n        color: #d4d4d4;\n      }\n      .token.number {\n        color: #b5cea8;\n      }\n      .token.comment {\n        color: #6a9955;\n      }\n      .token.class-name {\n        color: #4ec9b0;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"typing-code-block\"\n      data-start=\"0\"\n      data-duration=\"6\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"6\" style=\"position:absolute;inset:0;background-color:#1e1e1e\"></div>\n      <div id=\"panel\" class=\"clip\" data-start=\"0\" data-duration=\"6\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const panel = document.getElementById(\"panel\");\n        const fontSize = view.width * 0.02;\n        panel.style.fontSize = fontSize + \"px\";\n        panel.style.padding = fontSize + \"px\";\n        panel.style.width = view.width * 0.8 + \"px\";\n        const tokenStyle = document.createElement(\"style\");\n        tokenStyle.textContent = \"#panel .token.function { color: \" + vars.color + \"; }\";\n        panel.append(tokenStyle);\n        const fullCode = \"const App = () => {\\n    const [count, setCount] = useState(0);\\n\\n    useEffect(() => {\\n        document.title = `Count: ${count}`;\\n    }, [count]);\\n\\n    return (\\n        <button onClick={() => setCount(c => c + 1)}>\\n             Clicked {count} times\\n        </button>\\n    );\\n};\";\n        const typingSpeed = 0.3;\n        const proxy = { time: 0 };\n        let lastKey = null;\n        function render() {\n          const frame = Math.round(proxy.time * 30);\n          const charIndex = Math.floor(frame / typingSpeed);\n          const showCursor = Math.floor(frame / 15) % 2 === 0;\n          const key = charIndex + \":\" + showCursor;\n          if (key === lastKey) return;\n          lastKey = key;\n          panel.innerHTML = \"\";\n          panel.append(tokenStyle);\n          const block = hyperbits.createCodeBlock(panel, {\n            code: fullCode.slice(0, charIndex) + (showCursor ? \"|\" : \" \"),\n            language: \"typescript\",\n            showLineNumbers: true,\n          });\n          block.style.fontSize = fontSize + \"px\";\n          hyperbits.codeLines(block).forEach(function (line) {\n            line.style.display = \"flex\";\n            const content = line.querySelector(\".hyperbits-code-content\");\n            content.style.display = \"block\";\n            content.style.width = \"100%\";\n          });\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 6, duration: 6, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"typing-code-block\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
