    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"text\",\"type\":\"string\",\"label\":\"Text\",\"default\":\"Typing with errors and variable speed...\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#ff6b6b\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #line {\n        position: relative;\n        z-index: 1;\n        color: #fcc192;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n      }\n      #cursor {\n        display: inline-block;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"variable-speed-typewriter\"\n      data-start=\"0\"\n      data-duration=\"13.33\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"13.33\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <span id=\"line\" class=\"clip\" data-start=\"0\" data-duration=\"13.33\"><span id=\"typed\"></span><span id=\"cursor\">_</span></span>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const line = document.getElementById(\"line\");\n        const typed = document.getElementById(\"typed\");\n        const cursor = document.getElementById(\"cursor\");\n        const text = String(vars.text);\n        line.setAttribute(\"aria-label\", text);\n        line.style.color = vars.color;\n        line.style.fontSize = vmin * 6 + \"px\";\n        const KEYBOARD_CHARS = \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,!? \";\n        const errorRate = 0.1;\n        const errorCorrectDelay = 10;\n        const deleteSpeed = 2;\n        const blinkSpeed = 20;\n        const events = [{ frame: 0, text: \"\" }];\n        let floatFrame = 0;\n        let current = \"\";\n        function push() { events.push({ frame: Math.round(floatFrame), text: current }); }\n        const characters = hyperbits.splitUnits(text, \"chars\");\n        const length = characters.length;\n        for (let index = 0; index < length; index += 1) {\n          const progress = index / Math.max(1, length);\n          const charSeed = \"typewriter-0-\" + index;\n          const typeSpeed = hyperbits.interpolateKeyframes([2, 10, 2], progress);\n          if (hyperbits.random(charSeed) < errorRate) {\n            const wrongChar = KEYBOARD_CHARS[hyperbits.randomInt(charSeed + \"-wrong\", 0, KEYBOARD_CHARS.length - 1)];\n            floatFrame += typeSpeed;\n            current += wrongChar;\n            push();\n            floatFrame += errorCorrectDelay;\n            push();\n            floatFrame += deleteSpeed;\n            current = current.slice(0, -1);\n            push();\n          }\n          floatFrame += typeSpeed;\n          current += characters[index];\n          push();\n        }\n        const proxy = { time: 0 };\n        function render() {\n          const frame = Math.round(proxy.time * 30);\n          let active = 0;\n          for (let index = 0; index < events.length; index += 1) {\n            if (events[index].frame <= frame) active = index; else break;\n          }\n          typed.textContent = events[active].text;\n          cursor.style.opacity = frame % blinkSpeed < blinkSpeed / 2 ? \"1\" : \"0\";\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 13.33, duration: 13.33, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"variable-speed-typewriter\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
